const raw = $input.first().json.output?.[0]?.content?.[0]?.text || '{}';
const payload = typeof raw === 'string' ? JSON.parse(raw.trim()) : raw;
const form = $('Market Research Request Form').first().json;
return (Array.isArray(payload.competitors) ? payload.competitors.slice(0, 3) : []).filter(c => c && c.name).map(c => ({ json: { research_run_id: String($execution.id), target_company: String(form.company_name || ''), competitor_name: String(c.name || ''), competitor_website: String(c.website || 'not publicly available'), pricing: 'not publicly available', features: 'not publicly available', positioning: 'not publicly available', validation_status: 'pending', updated_at: new Date().toISOString() } }));

const raw = $('Select Direct Competitors').first().json.output?.[0]?.content?.[0]?.text || '{}';
const cleaned = typeof raw === 'string' ? raw.trim() : raw;
const payload = typeof cleaned === 'string' ? JSON.parse(cleaned) : cleaned;
const competitors = Array.isArray(payload.competitors) ? payload.competitors.slice(0, 3) : [];
const form = $('Market Research Request Form').first().json;
const lookbackDays = Math.max(1, Number(form.news_lookback_period) || 30);
const topics = [{ category: 'official_products', terms: 'current official website product pages products services', fresh: false }, { category: 'pricing', terms: 'current official pricing plans costs fees', fresh: false }, { category: 'core_features', terms: 'current official core features capabilities solutions', fresh: false }, { category: 'target_customers', terms: 'current official target customers industries clients case studies', fresh: false }, { category: 'market_positioning', terms: 'current official market positioning value proposition competitors', fresh: false }, { category: 'customer_reviews', terms: 'recent customer reviews testimonials G2 Capterra', fresh: false }, { category: 'funding_partnerships_launches_leadership', terms: 'recent official funding partnerships launches leadership press release news', fresh: false }, { category: 'recent_news', terms: 'recent official news announcements launches partnerships leadership', fresh: true }];
const output = [];
for (const competitor of competitors) { const competitorName = String(competitor.name || '').trim(); if (!competitorName) continue; const competitorWebsite = String(competitor.website || '').trim(); for (const topic of topics) { const sourceGuidance = ' Prefer official and recent sources. Use third-party sources only when official information is not publicly available.'; const query = (competitorName + ' ' + (competitorWebsite === 'not publicly available' ? '' : competitorWebsite) + ' ' + topic.terms + sourceGuidance).trim(); output.push({ json: { research_run_id: String($execution.id), company_name: String(form.company_name || ''), competitor_name: competitorName, competitor_website: competitorWebsite || 'not publicly available', category: topic.category, query, apply_freshness: topic.fresh, lookback_days: lookbackDays, retry_count: 0 } }); } }
return output;

const raw = $input.item.json.output?.[0]?.content?.[0]?.text || '{}';
let validation;
try { let text = typeof raw === 'string' ? raw.trim() : raw; if (typeof text === 'string') { const fence = String.fromCharCode(96).repeat(3); if (text.startsWith(fence)) text = text.slice(3).trimStart(); if (text.startsWith('json')) text = text.slice(4).trimStart(); if (text.endsWith(fence)) text = text.slice(0, -3).trimEnd(); const firstBrace = text.indexOf('{'); const lastBrace = text.lastIndexOf('}'); if (firstBrace >= 0 && lastBrace > firstBrace) text = text.slice(firstBrace, lastBrace + 1); validation = JSON.parse(text); } else validation = text; } catch (error) { validation = { complete: false, checks: {}, issues: ['Validator returned invalid JSON'], conflicting_sources: [], retry_query: '' }; }
const context = $('Attach Research Context').item.json;
const retryCount = Math.max(0, Number(context.retry_count) || 0);
const complete = validation.complete === true;
const issues = Array.isArray(validation.issues) ? validation.issues.map(String) : [];
return { json: { ...context, validation_complete: complete, validation_status: complete ? 'complete' : (retryCount >= 2 ? 'incomplete_after_retries' : 'incomplete'), validation_issues: issues, validation_checks: validation.checks || {}, conflicting_sources: Array.isArray(validation.conflicting_sources) ? validation.conflicting_sources : [], associated_claims: Array.isArray(validation.associated_claims) ? validation.associated_claims : [], category_summary: String(validation.category_summary || 'not publicly available'), retry_query: String(validation.retry_query || ''), retry_count: retryCount, ready_to_store: complete || retryCount >= 2 } };

const current = $input.item.json;
const validated = $('Parse Validation Result').item.json;
const summary = String(validated.category_summary || 'not publicly available');
let pricing = String(current.pricing || 'not publicly available');
let features = String(current.features || 'not publicly available');
let positioning = String(current.positioning || 'not publicly available');
if (validated.category === 'pricing') pricing = summary;
if (validated.category === 'core_features' || validated.category === 'official_products') features = summary;
if (validated.category === 'market_positioning') positioning = summary;
return { json: { research_run_id: String(validated.research_run_id), competitor_name: String(validated.competitor_name), pricing, features, positioning, validation_status: String(validated.validation_status || 'incomplete'), updated_at: new Date().toISOString() } };

const output = [];
for (const item of $input.all()) { const context = item.json; const results = context.search_results || {}; const sections = [{ sourceType: 'web', rows: Array.isArray(results.web) ? results.web : [] }, { sourceType: 'news', rows: Array.isArray(results.news) ? results.news : [] }]; for (const section of sections) { for (const result of section.rows) { const highlights = Array.isArray(result.contents?.highlights) ? result.contents.highlights : []; const snippets = Array.isArray(result.snippets) ? result.snippets : []; const excerptParts = []; if (result.description) excerptParts.push(String(result.description)); if (snippets.length) excerptParts.push(snippets.join(' ')); if (highlights.length) excerptParts.push(highlights.join(' ')); output.push({ json: { research_run_id: String(context.research_run_id || ''), competitor_name: String(context.competitor_name || ''), category: String(context.category || ''), source_type: section.sourceType, source_url: String(result.url || ''), source_title: String(result.title || ''), source_date: String(result.page_age || result.published_at || result.date || 'not publicly available'), excerpt: excerptParts.join(' ').slice(0, 5000), associated_claims: JSON.stringify((Array.isArray(context.associated_claims) ? context.associated_claims : []).filter(c => !c.url || String(c.url) === String(result.url || ''))), retrieved_at: new Date().toISOString(), validation_status: String(context.validation_status || 'incomplete'), validation_issues: Array.isArray(context.validation_issues) ? context.validation_issues.join(' | ') : String(context.validation_issues || ''), validation_checks_json: JSON.stringify(context.validation_checks || {}), conflicting_sources: JSON.stringify(context.conflicting_sources || []), retry_count: Number(context.retry_count || 0) } }); } } }
return output;

const item = $input.item.json;
const fallback = item.competitor_name + ' ' + item.category + ' current official source URL evidence';
const requested = String(item.retry_query || fallback).trim();
const query = requested.split(' ').filter(Boolean).slice(0, 45).join(' ').slice(0, 380);
return { json: { research_run_id: String(item.research_run_id || ''), company_name: String(item.company_name || ''), competitor_name: String(item.competitor_name || ''), competitor_website: String(item.competitor_website || 'not publicly available'), category: String(item.category || ''), query, apply_freshness: item.category === 'recent_news', lookback_days: Number(item.lookback_days || 30), retry_count: Number(item.retry_count || 0) + 1 } };

const form = $('Market Research Request Form').first().json;
const competitors = $('Get Report Competitors').all().map(item => item.json).filter(row => row && row.competitor_name);
const evidenceRows = $input.all().map(item => item.json).filter(row => row && row.source_url);
const expectedCategories = ['official_products', 'pricing', 'core_features', 'target_customers', 'market_positioning', 'customer_reviews', 'funding_partnerships_launches_leadership', 'recent_news'];
const exactlyThree = competitors.length === 3;
const allCategoriesPresent = exactlyThree && competitors.every(competitor => expectedCategories.every(category => evidenceRows.some(row => String(row.competitor_name) === String(competitor.competitor_name) && String(row.category) === category)));
const uniqueEvidence = [];
const seen = new Set();
for (const row of evidenceRows) { const url = String(row.source_url || '').trim(); if (!url || seen.has(url)) continue; seen.add(url); uniqueEvidence.push({ source_id: 'S' + (uniqueEvidence.length + 1), competitor_name: String(row.competitor_name || ''), category: String(row.category || ''), source_type: String(row.source_type || ''), source_url: url, source_title: String(row.source_title || ''), source_date: String(row.source_date || 'not publicly available'), excerpt: String(row.excerpt || '').slice(0, 1200), associated_claims: String(row.associated_claims || '[]'), validation_status: String(row.validation_status || 'incomplete'), validation_issues: String(row.validation_issues || ''), validation_checks_json: String(row.validation_checks_json || '{}'), conflicting_sources: String(row.conflicting_sources || '[]'), retry_count: Number(row.retry_count || 0) }); }
const successfulRecords = uniqueEvidence.filter(row => row.validation_status === 'complete');
const failedRecords = uniqueEvidence.filter(row => row.validation_status !== 'complete');
const context = { research_run_id: String($execution.id), target_company: String(form.company_name || ''), target_website: String(form.company_website || ''), industry: String(form.industry || ''), target_market: String(form.target_market || ''), country_or_region: String(form.country_or_region || ''), news_lookback_days: Math.max(1, Number(form.news_lookback_period) || 30), report_date: new Date().toISOString().slice(0, 10), competitors: competitors.map(row => ({ name: String(row.competitor_name || ''), website: String(row.competitor_website || 'not publicly available'), pricing: String(row.pricing || 'not publicly available'), features: String(row.features || 'not publicly available'), positioning: String(row.positioning || 'not publicly available'), validation_status: String(row.validation_status || 'incomplete') })), successful_records: successfulRecords, failed_or_incomplete_records: failedRecords, evidence: uniqueEvidence };
return [{ json: { report_ready: allCategoriesPresent && failedRecords.length === 0, competitor_count: competitors.length, evidence_count: evidenceRows.length, successful_record_count: successfulRecords.length, failed_record_count: failedRecords.length, report_context_json: JSON.stringify(context) } }];

const raw = $input.first().json.output?.[0]?.content?.[0]?.text || '';
const report = typeof raw === 'string' ? raw.trim() : JSON.stringify(raw, null, 2);
const form = $('Market Research Request Form').first().json;
const context = $('Build Report Context').first().json;
const title = 'Competitive Market Research - ' + String(form.company_name || 'Company') + ' - ' + new Date().toISOString().slice(0, 10);
const safeName = title.replace(/[^a-zA-Z0-9._ -]/g, '').replace(/\s+/g, '_');
const escapeRtf = (value) => String(value).replace(/\\/g, '\\\\').replace(/\{/g, '\\{').replace(/\}/g, '\\}').replace(/[^\x20-\x7E]/g, character => '\\u' + character.charCodeAt(0) + '?');
const lines = report.split(/\r?\n/);
const rtfLines = lines.map(line => { const text = String(line); if (/^###\s+/.test(text)) return '\\par \\b\\fs24 ' + escapeRtf(text.replace(/^###\s+/, '')) + '\\b0\\fs22'; if (/^##\s+/.test(text)) return '\\par \\b\\fs28 ' + escapeRtf(text.replace(/^##\s+/, '')) + '\\b0\\fs22'; if (/^#\s+/.test(text)) return '\\par \\b\\fs32 ' + escapeRtf(text.replace(/^#\s+/, '')) + '\\b0\\fs22'; if (/^[-*]\s+/.test(text)) return '\\par \bullet\tab ' + escapeRtf(text.replace(/^[-*]\s+/, '')); return '\\par ' + escapeRtf(text.replace(/\*\*/g, '')); });
const rtfContent = '{\\rtf1\\ansi\\deff0{\\fonttbl{\\f0 Calibri;}}\\viewkind4\\uc1\\fs22 \\b\\fs36 ' + escapeRtf(title) + '\\b0\\fs22 ' + rtfLines.join('') + '}';
const status = context.report_ready ? 'completed' : 'completed_with_gaps';
return [{ json: { title, file_name: safeName + '.rtf', rtf_content: rtfContent, completion_status: status } }];
